<?php $testCardInstance=($testCardInstance??0)+1;$now=time();$starts=strtotime($test['starts_at']);$ends=strtotime($test['ends_at']);$dialogId='enrollTest'.(int)$test['id'].'-'.$testCardInstance;$currentUser=\App\Core\Auth::user();$studentLoggedIn=$currentUser&&$currentUser['role']==='student';?>
<article class="test-card" data-explore-card data-title="<?=e(strtolower($test['title']))?>" data-exam="<?=e(strtolower($test['exam_name']))?>" data-category="<?=e(strtolower($test['category']))?>" data-subject="<?=e(strtolower($test['subject']))?>"><?php if(!empty($test['thumbnail_path'])):?><img class="test-thumbnail" src="/cbt/media/<?=e($test['thumbnail_path'])?>" alt="<?=e($test['title'])?> thumbnail"><?php endif;?><div class="card-tags"><span class="subject"><?=e($test['subject'])?></span><span class="test-card-meta"><?=e($test['exam_name'])?> · <?=e($test['category'])?></span></div><h3><?=e($test['title'])?></h3><div class="test-facts"><span><b><?=e($test['total_questions'])?></b> Questions</span><span><b><?=e($test['full_marks'])?></b> Marks</span><span><b><?=e($test['duration_minutes'])?></b> Minutes</span></div><div class="schedule"><span>Starts <b><?=e(date('d M, h:i A',$starts))?></b></span><span>Ends <b><?=e(date('d M, h:i A',$ends))?></b></span></div><div class="test-card-foot"><b><?=((float)$test['fee']>0)?'₹'.e($test['fee']):'FREE'?></b><?php if(!$studentLoggedIn):?><a class="btn small" href="/cbt/test/<?=e($test['id'])?>">View &amp; enroll</a><?php elseif(($test['attempt_status']??'')==='submitted'):?><a class="btn small" href="/cbt/result/<?=e($test['attempt_id'])?>" aria-label="View result">◉ Result</a><?php elseif(($test['enrollment_status']??'')==='active'&&$now<$starts):?><button class="btn small disabled" disabled title="Test has not started">Starts soon</button><?php elseif(($test['enrollment_status']??'')==='active'&&$now>$ends):?><button class="btn small disabled" disabled>Window closed</button><?php elseif(($test['enrollment_status']??'')==='active'):?><a class="btn small" href="/cbt/exam/<?=e($test['id'])?>/instructions"><?=($test['attempt_status']??'')==='in_progress'?'Continue':'View test'?></a><?php else:?><button class="btn small" type="button" data-dialog-target="<?=e($dialogId)?>">Enroll now</button><?php endif;?></div></article>
<?php if($studentLoggedIn&&($test['enrollment_status']??'')!=='active'&&($test['attempt_status']??'')!=='submitted'):?><dialog id="<?=e($dialogId)?>" class="enrollment-dialog"><button class="dialog-close" type="button" data-dialog-close>×</button><span class="eyebrow">TEST ENROLLMENT</span><h2><?=e($test['title'])?></h2><div class="detail-table"><div><span>Fee</span><b><?=((float)$test['fee']>0)?'₹'.e($test['fee']):'Free'?></b></div><div><span>Start date &amp; time</span><b><?=e(date('d M Y, h:i A',$starts))?></b></div><div><span>End date &amp; time</span><b><?=e(date('d M Y, h:i A',$ends))?></b></div><div><span>Duration</span><b><?=e($test['duration_minutes'])?> minutes</b></div></div><div class="warning"><b>Important note:</b> You must start the exam before the end time. After the examination window closes, the test cannot be started. Please make sure you begin before the end time.</div><form method="post" action="/cbt/api/cbt/tests/<?=e($test['id'])?>/enroll" data-enrollment-form><?=csrf_field()?><button class="btn wide"><?=((float)$test['fee']>0)?'Continue to payment':'Enroll now'?></button></form></dialog><?php endif;?>

